// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 t, address actor) public {
        vm.assume(actor != address(c) && actor != address(0));
        vm.assume(t > 0);
        vm.assume(t < type(uint256).max - 2);

        vm.deal(actor, 20 ether);

        // first call at time t succeeds (sets pastBlockTime = t + 1)
        vm.warp(t);
        vm.roll(block.number + 1);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // general rule: no call may succeed at time t + 1
        vm.warp(t + 1);
        vm.roll(block.number + 1);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertTrue(!ok2);
    }
}
